section.piece_a:
class RateQuote
  TTL = 60.seconds

  def initialize(client)
    @client = client
  end

  def convert(amount_cents, from:, to:)
    rate = Rails.cache.fetch(["fx-rate", from, to], expires_in: TTL) do
      @client.rate(from: from, to: to)
    end
    (amount_cents * rate).round
  end
end

